const recipes=[{title:'Fire-kissed peppers',category:'vegetables',time:'25 MIN',image:'assets/fire.jpg',description:'Smoky peppers, sweet tomatoes and a bright herb finish.',ingredients:['Sweet peppers','Cherry tomatoes','Olive oil','Parsley and lemon','Sea salt'],method:'Toss peppers and tomatoes with oil. Cook in a fire-safe pan over medium coals, turning until softened and lightly charred. Finish with parsley, lemon and salt.'},{title:'The ember flatbread',category:'sides',time:'35 MIN',image:'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=1000&q=85',description:'Warm, blistered bread made for tearing and sharing.',ingredients:['Flatbread dough','Olive oil','Flaky salt','Fresh herbs'],method:'Divide prepared dough into small rounds. Brush with oil, then cook on a hot grate or fire-safe pan until puffed and cooked through, turning once. Finish with salt and herbs.'},{title:'Charred market vegetables',category:'mains',time:'40 MIN',image:'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=1000&q=85',description:'A generous platter of seasonal vegetables and smoky dressing.',ingredients:['Seasonal vegetables','Olive oil','Lemon','Plain yogurt','Garlic'],method:'Cut vegetables into even pieces and coat lightly in oil. Grill over steady coals until tender and charred. Stir lemon and garlic into yogurt, then serve alongside.'}];const grid=document.querySelector('#recipeGrid');const dialog=document.querySelector('#recipeDialog');let trigger;function render(filter='all'){grid.innerHTML=recipes.map((r,i)=>({r,i})).filter(({r})=>filter==='all'||r.category===filter).map(({r,i})=>`<article class="recipe-card"><button data-recipe="${i}" aria-label="View recipe: ${r.title}"><div class="recipe-image"><img src="${r.image}" alt="${r.title}" loading="lazy"></div><div class="recipe-meta"><span>${r.category.toUpperCase()}</span><span>${r.time}</span></div><h3>${r.title}</h3><p>${r.description}</p></button></article>`).join('')}document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});render(button.dataset.filter)}));grid.addEventListener('click',e=>{const button=e.target.closest('[data-recipe]');if(!button)return;trigger=button;const r=recipes[+button.dataset.recipe];document.querySelector('#dialogTag').textContent=r.category.toUpperCase()+' · '+r.time;document.querySelector('#dialogTitle').textContent=r.title;document.querySelector('#dialogDesc').textContent=r.description;document.querySelector('#dialogIngredients').innerHTML=r.ingredients.map(x=>`<li>${x}</li>`).join('');document.querySelector('#dialogMethod').textContent=r.method;dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>trigger?.focus());render();
